--   - 12 total agents under pack='toro' (3 LIVE from PR #117 + 9 newly activated)
--   - 12 is_active=TRUE
--
-- Idempotent. Safe to re-run.

BEGIN;

-- Activate Tōro parent + 8 sub-agents
UPDATE agent_prompts
  SET is_active = TRUE, updated_at = now()
WHERE pack = 'toro'
  AND agent_name IN (
    'toro',
    'toro-education',
    'toro-email',
    'toro-family',
    'toro-health',
    'toro-home',
    'toro-homework',
    'toro-logistics',
    'toro-money'
  )
  AND is_active = FALSE;  -- only flip currently-inactive rows

-- Capture how many rows actually flipped
DO $$
DECLARE
  flipped int;
  current_active int;
BEGIN
  SELECT count(*) INTO current_active FROM agent_prompts WHERE pack = 'toro' AND is_active = TRUE;
  RAISE NOTICE 'pack=toro now has % active rows', current_active;
  -- expect 12: 3 (PR #117) + 9 (today's port + Reo's pass)
END $$;

COMMIT;

